<?php require 'app/init.php';require 'app/view.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM clubes WHERE id=?');$s->execute([$id]);$club=$s->fetch();if(!$club){http_response_code(404);exit('Club no encontrado');}$u=me();if($_SERVER['REQUEST_METHOD']==='POST'){$u=require_user();verify();if(($_POST['accion']??'')==='unirse')db()->prepare('INSERT IGNORE INTO miembros_club(club_id,usuario_id) VALUES(?,?)')->execute([$id,$u['id']]);if(($_POST['accion']??'')==='mensaje'){$check=db()->prepare('SELECT 1 FROM miembros_club WHERE club_id=? AND usuario_id=?');$check->execute([$id,$u['id']]);$body=trim($_POST['contenido']??'');if($check->fetch()&&$body&&mb_strlen($body)<=2000)db()->prepare('INSERT INTO mensajes_club(club_id,usuario_id,contenido) VALUES(?,?,?)')->execute([$id,$u['id'],$body]);}go('club.php?id='.$id);}top($club['nombre']);?><main class="card" style="max-width:850px;margin:30px auto"><a href="clubes.php">← Clubes</a><h1><?=e($club['nombre'])?></h1><p><?=e($club['descripcion'])?></p><?php $member=false;if($u){$s=db()->prepare('SELECT 1 FROM miembros_club WHERE club_id=? AND usuario_id=?');$s->execute([$id,$u['id']]);$member=(bool)$s->fetch();}if($u&&!$member):?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><button name="accion" value="unirse">Unirme al club</button></form><?php endif;?><h2>Conversación</h2><?php $s=db()->prepare('SELECT m.*,u.nombre FROM mensajes_club m JOIN usuarios u ON u.id=m.usuario_id WHERE m.club_id=? ORDER BY m.creado_en DESC LIMIT 50');$s->execute([$id]);foreach(array_reverse($s->fetchAll()) as $m):?><div class="comment"><strong><?=e($m['nombre'])?></strong><p><?=e($m['contenido'])?></p></div><?php endforeach;?><?php if($member):?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><textarea name="contenido" required maxlength="2000" placeholder="Escribe en el club"></textarea><button name="accion" value="mensaje">Enviar</button></form><?php endif;?></main><?php bottom();?>